#!/usr/bin/env python3
"""Generate the semicolon-terminated HTML5 named character reference table."""

from html.entities import html5
import json
from pathlib import Path


output = Path(__file__).resolve().parents[1] / "lib/liwus/webdom_entities.inc"
records = sorted(
    (name[:-1], value)
    for name, value in html5.items()
    if name.endswith(";")
)

lines = [
    "/* Generated by scripts/gen_webdom_entities.py from Python's HTML5 entity table. */",
]
for name, value in records:
    codepoints = [ord(ch) for ch in value]
    first = codepoints[0]
    second = codepoints[1] if len(codepoints) > 1 else 0
    lines.append(f"    {{ {json.dumps(name)}, 0x{first:04x}U, 0x{second:04x}U }},")

output.write_text("\n".join(lines) + "\n", encoding="ascii")
print(f"wrote {len(records)} HTML5 named references to {output}")
